package com.ke.ticketsystemke.service;import org.slf4j.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(name="warranty.reminders.enabled",havingValue="true")public class WarrantyReminderScheduler{private static final Logger log=LoggerFactory.getLogger(WarrantyReminderScheduler.class);private final WarrantyReminderGenerationService service;public WarrantyReminderScheduler(WarrantyReminderGenerationService s){service=s;}@Scheduled(cron="${warranty.reminders.daily-cron:0 0 8 * * *}",zone="${warranty.reminders.timezone:Asia/Kolkata}")public void generate(){var result=service.generate();log.info("event=warranty_reminder_generation_completed runId={} claimsScanned={} created={} updated={} resolved={} failures={}",result.runId(),result.claimsScanned(),result.remindersCreated(),result.remindersUpdated(),result.remindersResolved(),result.failures());}}
